`timescale 1ns/1ps
// Basys 3 top level - generated by scripts/make_experiments.py
module top_basys3 (
    input  wire        clk,                    // 100 MHz
    input  wire        btnC, btnU, btnL, btnR, // btnC = reset
    input  wire [15:0] sw,
    output wire [15:0] led,
    output wire [3:0]  an,
    output wire [6:0]  seg
);
    wire rst = btnC;
    wire en;   // one model step every 1/200 s, slow enough to watch
    step_tick #(.STEP_HZ(200)) u_tick (.clk(clk), .rst(rst), .tick(en));
    wire signed [31:0] i_in = {19'd0, sw[4:0], 8'd0};   // I = sw[4:0], try 10
    wire signed [31:0] v0, v1, v2, v3, u0, u1, u2, u3;  wire s0, s1, s2, s3;
    izh_neuron #(.A(5),  .B(51), .C(-65*256), .D(8*256)) u_rs (clk, rst, en, i_in, v0, u0, s0);   // regular spiking
    izh_neuron #(.A(5),  .B(51), .C(-55*256), .D(4*256)) u_ib (clk, rst, en, i_in, v1, u1, s1);   // intrinsically bursting
    izh_neuron #(.A(5),  .B(51), .C(-50*256), .D(2*256)) u_ch (clk, rst, en, i_in, v2, u2, s2);   // chattering
    izh_neuron #(.A(26), .B(51), .C(-65*256), .D(2*256)) u_fs (clk, rst, en, i_in, v3, u3, s3);   // fast spiking
    wire [1:0] sel = sw[15:14];
    wire signed [31:0] v = (sel == 0) ? v0 : (sel == 1) ? v1 : (sel == 2) ? v2 : v3;
    wire spike = (sel == 0) ? s0 : (sel == 1) ? s1 : (sel == 2) ? s2 : s3;
    wire spike_led;
    pulse_stretch u_ps (.clk(clk), .rst(rst), .in(spike), .out(spike_led));
    wire signed [31:0] bar_val = (v >>> 8) + 80;
    bar15 #(.FULL(110)) u_bar (.val(bar_val), .leds(led[14:0]));
    assign led[15] = spike_led;
    wire signed [31:0] num = v >>> 8;
    seg7_signed u_seg (.clk(clk), .value(num[15:0]), .an(an), .seg(seg));
endmodule
